import type{ReactNode}from'react';import{F2DeepDive,f2Quiz}from'./fashionM2Core';import type{FashionM2Question,FashionM2Source,FashionM2Takeaways}from'./fashionM2Core';import{VisualView}from'./fashionVisualKit';import type{VisualSpec}from'./fashionVisualKit';import{AUDIT_ASSURANCE_CHAPTER_VISUALS}from'./auditAssuranceVisualSpecs';export const AUDIT_SOURCES={iaasbHandbook:{title:'IAASB 2023–2024 Handbook — Volume I',href:'https://ifacweb.blob.core.windows.net/publicfiles/2024-08/IAASB-2023-2024-Handbook-Volume-1.pdf',publisher:'International Auditing and Assurance Standards Board',note:'Authoritative international standards context including ISA 200, risk, evidence, reporting and group audits; local adoption and amendments must be verified.'},isa315:{title:'ISA 315 (Revised 2019) — Risk Identification and Assessment',href:'https://www.iaasb.org/publications/isa-315-revised-2019-identifying-and-assessing-risks-material-misstatement',publisher:'International Auditing and Assurance Standards Board',note:'Official risk-assessment standard page; apply the standards and legal framework effective in the relevant jurisdiction and period.'},iaasbQuality:{title:'IAASB Quality Management Standards',href:'https://www.iaasb.org/focus-areas/quality-management',publisher:'International Auditing and Assurance Standards Board',note:'Official context for ISQM 1, ISQM 2 and ISA 220 (Revised), effective 15 December 2022 internationally; local adoption may differ.'},otherEngagements:{title:'ISAE 3000 (Revised)',href:'https://www.iaasb.org/publications/international-standard-assurance-engagements-isae-3000-revised-assurance-engagements-other-audits-or',publisher:'International Auditing and Assurance Standards Board',note:'Official standard page for assurance other than audits or reviews of historical financial information; engagement-specific and jurisdictional requirements still apply.'},aups:{title:'ISRS 4400 (Revised) — Agreed-Upon Procedures',href:'https://www.iaasb.org/publications/international-standard-related-services-isrs-4400-revised',publisher:'International Auditing and Assurance Standards Board',note:'Agreed-upon procedures report procedures and factual findings and do not express an audit opinion or assurance conclusion.'},isa600:{title:'ISA 600 (Revised) — Group Audits',href:'https://www.iaasb.org/publications/international-standard-auditing-600-revised-special-considerations-audits-group-financial-statements',publisher:'International Auditing and Assurance Standards Board',note:'Official group-audit standard page; effective internationally for periods beginning on or after 15 December 2023, subject to local adoption.'},issa5000:{title:'ISSA 5000 — Sustainability Assurance',href:'https://ifacweb.blob.core.windows.net/publicfiles/2025-01/IAASB-International-Standard-on-Sustainability-Assurance-ISSA-5000.pdf',publisher:'International Auditing and Assurance Standards Board',note:'Final international standard, not yet generally effective as of October 2026; effective for periods beginning on or after 15 December 2026, with earlier application permitted.'},iesba:{title:'IESBA 2025 Code of Ethics and Independence Standards',href:'https://www.ethicsboard.org/iesba-code',publisher:'International Ethics Standards Board for Accountants',note:'Global ethics and independence framework; jurisdictional adoption, effective dates and local requirements must be verified.'},technology:{title:'Technology and the Future of Audit and Assurance',href:'https://www.iaasb.org/focus-areas/technology',publisher:'International Auditing and Assurance Standards Board',note:'Official technology-position and quality-management context; technology supports but does not replace evidence evaluation, professional skepticism or accountability.'},fraud:{title:'ISA 240 (Revised) — Fraud',href:'https://www.iaasb.org/publications/isa-240-revised-auditor-s-responsibilities-relating-fraud-audit-financial-statements',publisher:'International Auditing and Assurance Standards Board',note:'Final revised standard, effective internationally for periods beginning on or after 15 December 2026; local adoption and early application must be checked.'},goingConcern:{title:'ISA 570 (Revised 2024) — Going Concern',href:'https://www.iaasb.org/publications/isa-570-revised-2024-going-concern',publisher:'International Auditing and Assurance Standards Board',note:'Final revised standard, effective internationally for periods beginning on or after 15 December 2026; local adoption and early application must be checked.'},vnAuditLaw:{title:'Law on Independent Audit No. 67/2011/QH12',href:'https://vbpl.vn/botaichinh/Pages/vbpq-toanvan.aspx?ItemID=26750',publisher:'Vietnam National Legal Database — Ministry of Finance',note:'Official law effective 1 January 2012 and currently partially effective; verify amendments and current implementing rules for each entity and service.'},vnStandards:{title:'Circular No. 214/2012/TT-BTC — Vietnam Auditing Standards',href:'https://vbpl.vn/TW/Pages/vbpq-van-ban-goc.aspx?ItemID=30478',publisher:'Vietnam National Legal Database',note:'Official record effective 1 January 2014 and shown as in force; verify later amendments, additional standards and engagement-specific requirements.'},vnData:{title:'Law on Personal Data Protection No. 91/2025/QH15',href:'https://congbao.chinhphu.vn/van-ban/luat-so-91-2025-qh15-45578.htm',publisher:'Official Gazette of Vietnam',note:'Official law effective 1 January 2026; duties depend on processing role, data, purpose, scale and current guidance.'}} satisfies Record<string,FashionM2Source>;export type AuditSourceId=keyof typeof AUDIT_SOURCES;export type AuditVisualKind=`professional-audit-m${number}-${number}`;export interface AuditCardData{title:string;chapterTitle:string;readingTime:string;legacyIndex?:number;legacyIndexes?:number[];legacyCompletionIndex?:number;migrationVersion?:string;objective:string;mateIntro:string;keyInsight:string;concepts:[];narrative:Array<{label:'What it is'|'Why it is happening'|'Real-world example'|'Vietnam example'|'Business impact';text:string}>;visualKind:AuditVisualKind;visualHeading:string;visualIntro:string;imageAlt:string;statTiles:Array<{value?:string;label:string;subtitle?:string;description:string}>;statsNote:string;keyTerms:Array<{term:string;definition:string}>;recap:string[];chapterRecap:string;deepDiveTitle:string;body:ReactNode;sources:FashionM2Source[]}export type AuditStat={value?:string;label:string;subtitle?:string;description:string};export type AuditItem={title:string;dimensions:string[];insight:string;scope:string;example:string;vietnam:string;sources:AuditSourceId[];stats?:AuditStat[];intro?:string;definitions?:Record<string,string>;legacyIndex?:number;legacyIndexes?:number[];legacyCompletionIndex?:number};export type AuditLesson=[string,AuditItem[]];

