type AuditDetail={dimensions:string[];scope:string;insight:string;example:string;vietnam:string;intro?:string;sources?:AuditSourceId[];definitions?:Record<string,string>};
const AUDIT_DETAILS:Record<string,AuditDetail>={
'Where Does Audit Begin and End?':{dimensions:['External audit','Internal audit','Accounting','Bookkeeping','Consulting','Management responsibility','Regulatory oversight'],scope:'External audit independently evaluates financial statements under an applicable framework. Internal audit supports governance and controls; accounting prepares records and statements; consulting advises; management remains responsible for financial statements and controls.',insight:'Audit is not accounting, internal audit or consulting. An external financial statement audit provides reasonable—not absolute—assurance and does not guarantee error-free statements or detection of every fraud.',example:'Management prepares revenue records and estimates; the external auditor assesses risks and evidence before expressing an opinion.',vietnam:'Verify statutory scope, eligible firm and auditor, independence, applicable VSA, reporting framework and entity-specific requirements.'},
'How Are Materiality and Performance Materiality Applied?':{dimensions:['Benchmark','Overall materiality','Performance materiality','Qualitative factor','Revision','Accumulated misstatement'],scope:'Materiality guides planning, procedures and evaluation based on what could influence intended users. Performance materiality is set below overall materiality to reduce aggregation risk; neither is a permitted error allowance.',insight:'HYPOTHETICAL — If a team illustrates overall materiality as 5% of VND100bn normalized profit, the result is VND5bn; choosing VND3.5bn performance materiality is an engagement judgment, not a universal rule or safe error amount.',example:'HYPOTHETICAL calculation: 100bn×5%=5bn overall illustration; 3.5bn performance materiality reflects the stated hypothetical risk judgment. Qualitative matters can still be material below either amount.',vietnam:'Apply current standards, entity context and documented professional judgment; do not present the illustrative percentage as a Vietnam requirement.'},
'How Are Risks of Material Misstatement Assessed?':{dimensions:['Inherent risk','Control risk','Detection risk','Risk of material misstatement','Fraud risk','Business risk','Engagement risk'],scope:'Risk assessment identifies where material misstatement may arise and designs responses. The simplified planning model expresses Audit Risk = Inherent Risk × Control Risk × Detection Risk; it is not a literal company-wide probability calculation.',insight:'Audit risk differs from business, fraud and engagement risk. Higher assessed inherent or control risk generally requires lower acceptable detection risk through changed nature, timing or extent of procedures.',example:'A complex revenue estimate with weak controls can lead to more year-end testing, external evidence, larger or targeted selections and specialist involvement.',vietnam:'Use applicable VSA requirements and engagement evidence; do not invent universal probabilities or sample sizes.'},
'How Are Sampling, Evidence and Documentation Evaluated?':{dimensions:['Evidence relevance','Evidence reliability','Evidence quantity','Sampling risk','Contradictory evidence','Audit documentation','Professional judgment'],scope:'Auditors obtain sufficient appropriate evidence through inspection, observation, confirmation, recalculation, reperformance, inquiry and analytics as relevant. Quantity cannot compensate for poor relevance or reliability.',insight:'HYPOTHETICAL — When revenue risk rises because controls are weak, the auditor may shift work toward year-end substantive procedures, external confirmations and targeted unusual transactions; no universal sample size follows from risk alone.',example:'HYPOTHETICAL response: expand or retarget testing, improve source reliability and resolve contradictions while documenting why evidence supports the conclusion.',vietnam:'Procedure design and sample selection require current standards, population characteristics and professional judgment.'},
'How Are Audit Opinions and Other Report Elements Distinguished?':{dimensions:['Unmodified opinion','Qualified opinion','Adverse opinion','Disclaimer','Emphasis of Matter','Going concern','Other information'],scope:'Reporting outcomes depend on the matter, materiality, pervasiveness and evidence. An Emphasis of Matter draws attention to an appropriately presented matter and is not automatically a modified opinion.',insight:'An unmodified opinion is not a guarantee of financial health; qualified, adverse and disclaimer opinions communicate different circumstances and must not be treated as severity labels without context.',example:'A material but non-pervasive misstatement can lead to a qualified opinion; a material and pervasive misstatement can lead to an adverse opinion; inability to obtain sufficient evidence can lead to qualification or disclaimer depending on pervasiveness.',vietnam:'Use the reporting standard and legal framework effective for the entity and period; verify current wording and required report elements.'},
'Which Financial Reporting Areas Commonly Drive Audit Work?':{dimensions:['Revenue recognition','Inventory valuation','Receivables and ECL','Provisions','Going concern','Management estimates','Related parties','Disclosures'],scope:'Audit teams focus on assertions and risks within significant transaction classes, balances and disclosures, including revenue, inventory, receivables, provisions, estimates, related parties and going concern.',insight:'The curriculum identifies audit implications without attempting to replace the full applicable accounting standards or management judgments.',example:'For inventory, existence, condition, costing and net realizable value may require different evidence; for revenue, occurrence, cutoff and contract terms can drive procedures.',vietnam:'Apply the entity’s actual reporting framework and current accounting and audit requirements; do not infer one universal treatment.'},
'How Do Audit Engagements Generate Revenue?':{dimensions:['Fixed fee','Scope-based fee','Milestone billing','Recurring engagement','Additional assurance','Change procedure','Recognized revenue'],scope:'Audit firms earn fixed or scope-based engagement fees, milestone billings and permitted assurance fees. Contract value, invoice, recognized revenue, cash and profit occur on different bases.',insight:'HYPOTHETICAL — A VND1,200m fee less 4,000 professional hours at VND180,000 cost, VND120m specialists and VND160m other delivery cost gives VND200m contribution, or 16.7%.',example:'HYPOTHETICAL calculation: labor=4,000×0.18m=720m; total delivery cost=720+120+160=1,000m; contribution=1,200−1,000=200m; margin=16.7%.',vietnam:'Do not treat fee or margin as quality evidence; define tax, scope changes, collections, write-offs and cost basis.'},
'What Determines Audit Delivery Costs and Profitability?':{dimensions:['Audit staff','Partner supervision','Specialist','Technology','Training','Quality review','Insurance','Travel and administration'],scope:'Delivery cost includes staff time, partner and manager supervision, specialists, tools, training, quality management, compliance, liability, travel, rework and working capital.',insight:'High utilization or engagement margin does not automatically indicate high audit quality; commercial pressure must not override required evidence, supervision, independence or review.',example:'A low-fee engagement can require more senior time when records are weak or estimates complex; reducing procedures to protect margin is not an acceptable response.',vietnam:'Track hours, staffing, scope change, collection, rework and quality indicators separately.'},
'Which KPIs Explain Audit-Firm Performance?':{dimensions:['Audit fee','Chargeable hours','Utilization','Billing rate','Realization','Contribution margin','Revenue per professional','Staff leverage','Retention','Backlog','Quality indicator'],scope:'Financial KPIs describe capacity and economics; quality indicators can include consultation, review, training, workload, findings and remediation under defined methods.',insight:'Audit efficiency, fee and margin are not audit quality. Every KPI needs an entity, service scope, period, numerator, denominator and accounting basis.',example:'Two engagements with equal fees can have different hours, specialist needs, risk, review effort, collection timing and quality outcomes.',vietnam:'Do not rank firms on unmatched network revenue, local-entity revenue, audit-only fees, headcount or inspection indicators.'},
'How Do International Standards and Vietnam-Adopted Requirements Interact?':{dimensions:['ISA','VSA','ISQM','IESBA Code','Vietnam law','Local adoption','Effective date'],scope:'International standards and ethics materials provide authoritative global context, while Vietnam applicability depends on adopted standards, law, implementing instruments, entity and period.',insight:'A final or internationally effective standard is not automatically current Vietnam law; jurisdiction, edition, adoption and early-application status must be explicit.',example:'A revised ISA effective internationally for future periods should be presented as forthcoming unless current Vietnam adoption is verified.',vietnam:'Use current official Vietnamese sources and flag unresolved applicability as Verification Required — Do Not Publish.'},
'How Are Financial Audit and Other Assurance Services Segmented?':{dimensions:['Financial statement audit','Review','Other assurance engagement','Agreed-upon procedures','Assurance level','Intended user'],intro:'This chapter explains how audit and assurance services are separated into segments by assurance level, subject matter and intended user.',scope:'Audit and assurance services are segmented by the question each one answers, not by price. A financial statement audit gives reasonable assurance, expressed as an opinion, on historical financial statements. A review gives limited assurance on financial information. Other assurance engagements cover subject matter beyond historical financial information and are performed under ISAE 3000 (Revised). Agreed-upon procedures sit outside assurance: they report the procedures performed and factual findings only. Each segment differs in assurance level, subject matter, criteria and intended user.',insight:'Each segment is a different engagement with its own standard, report and level of confidence, so one segment’s conclusion cannot be reused as another’s. Whether a service is required by law or bought voluntarily changes who sets the requirement, not what the service is.',example:'A company needs audited financial statements, its lender asks for specified checks over a covenant calculation, and its board wants assurance over a management-prepared non-financial indicator. These are three segments: an audit opinion, agreed-upon procedures reporting factual findings, and an other-assurance engagement with its own criteria.',vietnam:'Check the legal basis for each segment: which entities must have a financial statement audit, who may perform it, and which Vietnamese Standards on Auditing apply under the Law on Independent Audit and Circular 214/2012/TT-BTC. Do not assume the ISAE 3000 (Revised) or ISRS 4400 (Revised) segments exist in Vietnamese practice in the same form; verify current adoption.',sources:['iaasbHandbook','otherEngagements','aups','vnAuditLaw','vnStandards'],definitions:{'Financial statement audit':'An engagement in which the auditor expresses an opinion, with reasonable assurance, on whether historical financial statements are prepared in accordance with an applicable financial reporting framework.','Review':'An assurance engagement on financial information that gives limited assurance, expressed as a conclusion in the form the applicable standard requires.','Other assurance engagement':'An assurance engagement that is neither an audit nor a review of historical financial information, performed under ISAE 3000 (Revised) and any standard for its subject matter.','Agreed-upon procedures':'An engagement under ISRS 4400 (Revised) in which specified procedures are performed and factual findings reported; no audit opinion or assurance conclusion is expressed.','Assurance level':'The degree of confidence an engagement gives its intended users: reasonable assurance for an audit, limited assurance for a review, and none for agreed-upon procedures.'}},
'How Do Review, Agreed-Upon Procedures and Advisory Differ?':{dimensions:['Review engagement','Limited assurance','Agreed-upon procedures','Factual findings','Advisory service','Independence limit'],intro:'This chapter compares reviews, agreed-upon procedures and advisory work by assurance level, report output and intended users.',scope:'A review gives limited assurance: the practitioner obtains less evidence than in an audit and concludes in the form the applicable standard requires. Agreed-upon procedures under ISRS 4400 (Revised) are performed for the parties who specified them and report the procedures and factual findings; no opinion or assurance conclusion is expressed, and users draw their own conclusions. Advisory work gives recommendations and no assurance, and providing it to an audit client can be limited by the independence requirements of the IESBA Code. The three differ in assurance level, report output and who relies on the result.',insight:'Agreed-upon procedures are not a lighter audit and advisory work is not assurance. Calling either an audit or a review, or reading it as one, gives users more confidence than the work supports.',example:'A lender asks for specified checks on receivables ageing and wants the findings listed. The practitioner performs the agreed procedures and reports what was found, and the lender decides what it means. If the lender instead wanted an opinion that the financial statements are fairly presented, it would need an audit.',vietnam:'Confirm which service the law or the contract actually requires before accepting an engagement, and use the title and report form that match the work. Whether and how ISRS 4400 (Revised) applies in Vietnam must be verified against current Vietnamese instruments such as Circular 214/2012/TT-BTC and later amendments; do not treat the international standard as local law.',sources:['aups','otherEngagements','iesba','iaasbHandbook','vnStandards'],definitions:{'Review engagement':'An assurance engagement on financial information that ends in a conclusion giving limited assurance.','Limited assurance':'A lower level of assurance than reasonable assurance, expressed in the form required by the applicable standard.','Agreed-upon procedures':'Specified procedures performed for specified parties and reported as factual findings; the practitioner expresses no opinion or assurance conclusion and users draw their own.','Factual findings':'The results of specified procedures, reported as found, without an opinion or assurance conclusion.','Advisory service':'Work that advises a client on how to act or improve; it gives no assurance conclusion and, for an audit client, can be limited by independence requirements.'}},
'Who Purchases or Requires Audit and Assurance?':{dimensions:['Statutory requirement','Voluntary engagement','Those charged with governance','Intended user','Appointing party','Group reporting need'],intro:'This chapter explains who requires or buys audit and assurance, and why the buyer is not always the party that relies on the report.',scope:'Audit and assurance are required or bought for different reasons. Law or regulation can require certain entities to have their financial statements audited. Other entities buy an audit voluntarily because owners, lenders, investors or a parent group ask for assurance. The party that appoints and pays for the work is often not the party that relies on the report, so intended users, not the buyer, define what the engagement must achieve. Management prepares the financial statements, and those charged with governance oversee that process.',insight:'The buyer is not always the user. Demand for assurance comes from legal requirements and from parties who want confidence in reported information, and independence is what protects intended users from the pressure of the party that pays.',example:'A company is audited because law requires it. A lender separately makes audited statements a loan condition, and a foreign parent needs reporting for its consolidated results. Three reasons create demand for audit work, yet the auditor’s responsibility is to the users who rely on the statements, so the engagement cannot be shaped around one buyer’s preference.',vietnam:'Whether an entity must be audited is a question for the Law on Independent Audit (No. 67/2011/QH12) and its current implementing rules. Verify it entity by entity rather than assuming that a label such as foreign-invested or listed is covered. Voluntary and contractual demand from lenders or parent groups must be confirmed from the contract or request.',sources:['iaasbHandbook','otherEngagements','vnAuditLaw','vnStandards'],definitions:{'Statutory requirement':'A requirement set by law or regulation that an entity’s financial statements be audited; which entities are covered depends on current legal rules.','Voluntary engagement':'An audit or assurance engagement an entity chooses to buy without a legal requirement, for example at the request of a lender, investor or owner.','Those charged with governance':'The people or bodies responsible for overseeing an entity’s direction and accountability and with whom the auditor communicates; management is the separate party that prepares the statements.','Intended user':'A person or group for whom the auditor’s report is prepared and who relies on it; identifying them shapes the engagement’s criteria and report.','Appointing party':'The party that engages and typically pays the auditor, which may differ from the parties that rely on the report.'}},
'How Do Public-Interest, Private, Group and Voluntary Needs Differ?':{dimensions:['Public-interest entity','Private company','Group audit','Voluntary audit','Reporting complexity','Additional independence requirement'],intro:'This chapter contrasts what public-interest, private, group and voluntary clients need from an audit and which extra requirements follow.',scope:'Public-interest entities have a wide group of stakeholders relying on their financial statements, so the IESBA Code and local law can add independence and oversight requirements. Private companies usually have narrower users, such as owners and lenders, and requirements depend on law and contract. For groups, the need is one coherent opinion built on component information, which brings in ISA 600 (Revised). Voluntary clients choose an audit for their own or a stakeholder’s reasons, with scope and standard set in the engagement terms. The four needs differ in who relies on the audit, how complex reporting is and which extra requirements apply.',insight:'A client’s category changes the requirements around the audit, not the need for sufficient appropriate evidence. Public-interest, private, group and voluntary audits all need that evidence, but their users, additional independence rules and coordination needs differ.',example:'A listed company’s audit may carry extra independence and oversight requirements. A small private company audited at its lender’s request has a narrower group of users. A multinational’s group audit needs the group team to direct and evaluate component auditors’ work, while a voluntary audit follows the terms agreed with the client.',vietnam:'Verify how Vietnamese law and its implementing rules classify an entity, for example whether it is treated as public-interest or listed, and which additional requirements follow. Do not import a definition or threshold from another jurisdiction, or from the IESBA Code, without checking local adoption.',sources:['iesba','isa600','iaasbHandbook','vnAuditLaw','vnStandards'],definitions:{'Public-interest entity':'An entity whose financial condition matters to a wide set of stakeholders, so ethics standards and law can add requirements; the exact definition and consequences depend on the applicable code and local law.','Private company':'An entity outside a public-interest category whose financial-statement users are usually narrower, such as owners and lenders; its requirements depend on law and contract.','Group audit':'An audit of financial statements that include the financial information of more than one component, where the group engagement team directs and evaluates component work under ISA 600 (Revised).','Voluntary audit':'An audit performed without a legal requirement; if it is an audit, it still follows the auditing standards stated in the engagement terms.','Reporting complexity':'How demanding an entity’s reporting is, for example across several components, frameworks or users, which drives audit scope and effort.'}},
'How Do Governance, Regulators and Intended Users Evaluate Audit?':{dimensions:['Governance oversight','Auditor communication','Regulatory inspection','Remediation','Reliance on the report','Audit quality indicator'],intro:'This chapter explains how those charged with governance, regulators and intended users each form a view of an audit.',scope:'Audit is judged by three groups looking at different things. Those charged with governance, such as an audit committee, evaluate the auditor through communications about the audit, independence and quality. Regulators evaluate audit through inspection of a firm’s quality management and selected engagements, and expect findings to be remediated. Intended users cannot see the work and judge an audit mainly through the auditor’s report and the reputation behind it. Each group needs different evidence of quality.',insight:'Quality is judged from outside through evidence, not claims. Communications, inspection results and remediation show whether the audit and the firm system behind it can be relied on, while the report alone tells users little about how well the work was done.',example:'An audit committee asks how the auditor assessed independence and handled a disagreement over an estimate. A regulator reviewing the firm looks at how quality deficiencies were identified, what caused them and whether remediation worked. A lender reading the report sees only the opinion.',vietnam:'Confirm from current Vietnamese law and regulation which bodies inspect audit firms, which communications and inspections are required and what follows from findings. Treat audit committee practice as a governance matter specific to each entity, and do not assume practice from another jurisdiction applies.',sources:['iaasbQuality','iesba','iaasbHandbook','vnAuditLaw','vnStandards'],definitions:{'Governance oversight':'The role of those charged with governance, such as an audit committee, in overseeing financial reporting and evaluating the auditor, including independence and quality.','Auditor communication':'What the auditor reports to those charged with governance, such as significant findings and independence matters, so they can evaluate the audit.','Regulatory inspection':'A review by an oversight body of a firm’s quality management and selected completed audits, whose findings can require the firm to respond.','Remediation':'Timely action to correct a quality deficiency and its root cause, with evidence that the correction works.','Reliance on the report':'Users’ decision to place confidence in audited information because an independent auditor reported on it; it is justified only if the audit was properly performed.'}},
'How Do Staffing, Leverage and Chargeable Hours Shape Economics?':{dimensions:['Staff leverage','Chargeable hours','Team hierarchy','Supervision','Capacity planning','Rework'],intro:'This chapter explains how team mix, supervision and chargeable time drive the cost and revenue of an audit engagement.',scope:'Engagement cost is driven by who does the work and for how many hours. A layered team of assistants, experienced staff, managers, directors, partners and specialists is allocated by risk and competence, and staff leverage describes the mix of senior and junior time. Chargeable hours are the part of that time that can be billed, so leverage and hours together turn capacity into engagement cost and revenue. Automation can change junior tasks, but judgment on complex estimates, contradictions and conclusions still needs experienced people and supervision.',insight:'Effective leverage matches task complexity with competence and supervision. Cutting senior time indiscriminately to protect margin increases rework and quality risk.',example:'In a qualitative illustration with no figures, a team cuts senior time on an engagement with complex estimates to improve margin. Review happens late and errors surface at completion. Rework adds hours that were not budgeted, so the saving can disappear while quality is exposed.',vietnam:'Plan qualified capacity for peak deadlines, language, sector knowledge, technology, group instructions, coaching and reviews rather than utilization alone, and keep supervision in line with the requirements that apply to the engagement.',sources:['iaasbQuality','technology','vnAuditLaw','vnStandards'],definitions:{'Staff leverage':'The mix of senior and junior time on an engagement; effective leverage matches task complexity with competence and supervision.','Chargeable hours':'Professional hours recorded against an engagement that can be billed under the agreed basis, as distinct from training, administration or idle capacity.','Team hierarchy':'The layers of an engagement team, from assistants and experienced staff to managers, directors, partners and specialists, allocated by risk and competence.','Supervision':'Direction and review of team members’ work by more experienced people; it is what allows junior time to be used without lowering quality.','Capacity planning':'Planning enough qualified people for deadlines and peak periods rather than relying on utilization alone.'}},
'How Do Utilization, Billing Rates and Realization Affect Revenue?':{dimensions:['Utilization','Billing rate','Realization','Chargeable hours','Engagement revenue','Fee dependence'],intro:'This chapter shows how utilization, billing rate and realization combine to shape engagement revenue, and where each can mislead.',scope:'In a simplified model, engagement revenue depends on how many hours are chargeable, the rate applied to them and how much of that effort is realized as fees earned. Utilization measures chargeable or productive time against available capacity. Billing rate values that time. Realization compares fees earned with the recorded or standard value of the effort. Each can mislead alone: high utilization with low realization means busy people earning little, and a high billing rate means little if the effort is later written down.',insight:'No single ratio explains revenue. Read utilization, billing rate and realization together under defined bases, and never treat them as measures of audit quality or as a reason to reduce required procedures.',example:'Two teams work the same hours at the same standard rate. One team’s scope grew without a change in fee, so part of its effort is written off. Its realization is lower and so is its revenue, even though high utilization made it look fully busy.',vietnam:'Define each ratio before comparing firms or engagements: which hours count as available and chargeable, which rate or standard value applies, which fee basis and tax treatment is used, and how scope changes and write-offs are recorded. Fee setting must still respect independence and fee-related requirements, including those in local law.',sources:['iaasbQuality','iesba','vnAuditLaw','vnStandards'],definitions:{'Utilization':'Chargeable or productive time relative to available professional capacity under a stated definition.','Billing rate':'The rate applied to chargeable time, or used to value standard effort; it is not the same as the fee actually earned.','Realization':'Fees earned relative to recorded or standard billable effort under a defined basis.','Chargeable hours':'Time recorded against an engagement that can be billed under the agreed basis.','Engagement revenue':'Fees earned on an engagement after the agreed basis, scope changes and write-offs; it differs from contract value, invoice and cash.'}},
'Why Must Audit Quality Indicators Remain Separate From Financial KPIs?':{dimensions:['Audit quality indicator','Financial KPI','Fee pressure','Quality management','Remediation','Independence'],intro:'This chapter explains why measures of audit quality must be kept apart from the financial measures a firm uses to run itself.',scope:'Financial KPIs describe capacity and economics: fees, hours, utilization and margin. Audit quality indicators inform a different judgment, whether the work was done with enough consultation, review, training, workload control and follow-up of findings. The two answer different questions and can move in opposite directions, so they are defined, reported and reviewed separately. IAASB quality-management standards expect firms to identify quality risks, respond, monitor and remediate, which needs quality evidence that is not mixed into commercial targets.',insight:'Efficiency, fee and margin are not evidence of audit quality. Blending commercial measures with quality indicators lets strong financial results hide weak quality and can reward pressure that erodes it.',example:'A firm reports rising margin and utilization. Separately, its quality indicators show late partner review and unresolved findings on several engagements. If only a combined scorecard were reported, the quality signal would disappear behind the financial result.',vietnam:'Define each indicator’s entity, period, numerator, denominator and basis, and report quality and financial measures in separate views. Do not rank firms on unmatched revenue, headcount or inspection indicators, and verify which quality information Vietnamese regulation requires firms to keep or report.',sources:['iaasbQuality','iesba','vnAuditLaw','vnStandards'],definitions:{'Audit quality indicator':'A defined measure used to inform judgments about audit quality, such as consultation, review, training, workload, findings and remediation; it is evidence to evaluate, not a score.','Financial KPI':'A measure of capacity or economics, such as fee, hours, utilization or margin, that says nothing on its own about whether an audit was well performed.','Fee pressure':'Pressure on the price or budget of an engagement that, if unmanaged, can weaken the procedures, supervision or staffing the engagement needs.','Quality management':'Firm and engagement systems for achieving quality objectives, identifying risks, implementing responses, monitoring and remediation.','Remediation':'Timely correction of a quality deficiency and its root cause, with evidence that the correction works.'}},
'Who Participates in the Audit and Assurance Ecosystem?':{dimensions:['Audited entity','Intended user','Audit firm','Oversight body','Standard setter','Those charged with governance','Technology provider'],intro:'This chapter maps the parties that prepare, rely on, perform, supervise and set requirements for audit and assurance.',scope:'The audit and assurance ecosystem links the people who prepare information, those who rely on it and those who shape how the work is done. Management of the audited entity prepares the information, and those charged with governance oversee it. Intended users such as investors and lenders rely on the result. Audit firms, sometimes within networks, perform the work. Standard setters such as the IAASB and the IESBA issue auditing, quality-management and ethics requirements; legal and oversight bodies license and supervise; and technology providers supply the tools and data platforms the work uses.',insight:'Each participant has a different role and interest, and credible assurance depends on keeping them distinct: management prepares, the auditor independently evaluates, users rely, and oversight and standards frame the work. Role confusion, such as an auditor acting as management, weakens the whole system.',example:'When a company’s financial statements are audited, management prepares them, the audit committee oversees the process, the firm audits against issued standards, an oversight body can inspect the firm, a platform provider supplies workflow software, and investors and lenders rely on the report.',vietnam:'Identify Vietnamese regulatory, professional and standard-setting roles from current official sources rather than from this chapter. Law 67/2011/QH12 and Circular 214/2012/TT-BTC are the starting points, and their current status and implementing rules must be verified. International standard setters influence Vietnam only through adoption.',sources:['iaasbHandbook','iesba','technology','vnAuditLaw','vnStandards'],definitions:{'Audited entity':'The entity whose financial statements or other subject matter are examined; its management prepares the information and remains responsible for it.','Intended user':'A party that relies on the information and the report, such as an investor, lender, owner or regulator.','Audit firm':'The professional practice that performs and reports on the engagement; it may belong to a network that shares methods and brand while member firms remain separate legal entities.','Oversight body':'A body with legal or regulatory authority over audit firms and auditors, for example for licensing, inspection or enforcement; which bodies apply in Vietnam must be verified.','Standard setter':'A body that issues auditing, quality-management or ethics standards, such as the IAASB for auditing and quality standards and the IESBA for the Code of Ethics.'}},
'How Do Regulators, Professional Bodies and Technology Providers Shape Delivery?':{dimensions:['Regulator','Professional body','Technology provider','Tool validation','Data protection','Quality inspection'],intro:'This chapter explains how outside parties shape the way audit and assurance engagements can be staffed, performed and documented.',scope:'Delivery is shaped by outside parties as well as by the firm. Regulators set the conditions to practise and can supervise through licensing and inspection. Professional bodies support ethics, continuing development and, depending on the jurisdiction, the adoption of standards. Technology providers supply the tools and data platforms through which work is performed, but using a tool does not transfer responsibility: IAASB technology material expects tool fitness, critical evaluation of outputs and protection of confidential information.',insight:'Delivery choices are made inside requirements the firm does not set. External requirements and tool dependencies change how work is performed, but accountability for the audit conclusion and its quality stays with the firm and the engagement team.',example:'A firm adopts a new analytics platform. It must confirm that the tool is fit for purpose, evaluate its outputs critically, control access to client data and keep the evidence required, because the provider does not take on the firm’s responsibility for the audit. If a regulator inspects the engagement, the firm must be able to show how the tool was used and assessed.',vietnam:'Identify the current Vietnamese licensing, inspection and professional requirements from official sources, and confirm data-protection duties under the Law on Personal Data Protection (No. 91/2025/QH15, effective 1 January 2026) for any tool that stores or processes client data. Which duties apply depends on the firm’s role, the data and the purpose.',sources:['iaasbQuality','iesba','technology','vnAuditLaw','vnStandards','vnData'],definitions:{'Regulator':'A public body with authority to license, supervise and enforce requirements on audit firms and auditors.','Professional body':'An organization of accountants or auditors that supports ethics, continuing professional development and, depending on the jurisdiction, standards for its members.','Technology provider':'A supplier of audit software, analytics, data hosting or collaboration tools used to deliver engagements; the firm remains responsible for the work.','Tool validation':'Testing that a tool is fit for purpose, with its outputs critically assessed, before it is relied on in an engagement.','Data protection':'Duties and controls for protecting personal data and confidential client information when it is stored, shared or processed with tools.'}},
'Who Are the Major Global Audit Network Types?':{dimensions:['Global network','Mid-tier network','Association of independent firms','Network firm','Network requirement','Group coordination'],intro:'This chapter describes the main types of audit network and what membership does and does not change for a firm.',scope:'Audit networks differ in size, reach and how closely members are tied together. Large global networks and mid-tier networks link member firms that share a brand, methodology, training and quality requirements while remaining separate legal entities. Looser associations or alliances of independent firms cooperate on referrals and standards with less common control. Under ISQM 1, a firm’s quality management must address any network requirements, and the IESBA Code can extend independence requirements to network firms. For groups, network type affects how readily work in other countries can be directed and evaluated under ISA 600 (Revised).',insight:'Network type describes how a firm is connected to others, not how good it is. Membership can add reach and a common method, but it does not remove each firm’s own responsibility for engagement quality and independence.',example:'A multinational group needs audits in several countries. A firm in a global or mid-tier network can use common instructions and methods to coordinate component work, while a firm in a looser association may rely more on referral and agreed procedures. Either way, the group engagement team must still evaluate component auditors’ work under ISA 600 (Revised).',vietnam:'Ask which kind of network or association a Vietnamese firm belongs to, what that membership requires of it and what it does not. The local firm’s own licensing, independence and quality obligations under Vietnamese requirements still apply and must be verified; network brand or reach is not evidence of quality on a particular engagement.',sources:['iaasbQuality','iesba','isa600','iaasbHandbook','vnAuditLaw'],definitions:{'Global network':'A large international network of member firms that share brand, methodology and quality requirements and can coordinate audits of multinational groups.','Mid-tier network':'A smaller international network, with narrower reach or range of services than the largest networks, whose member firms still share methods and coordinate work.','Association of independent firms':'A looser grouping of independent firms that cooperate on referrals and shared standards; how much is shared varies by association.','Network firm':'A firm that belongs to a network; member firms remain separate legal entities, and the IESBA Code can extend independence requirements to network firms.','Network requirement':'A policy or requirement set by a network that member firms must implement, such as methodology or quality monitoring; a firm’s quality management must address it under ISQM 1.'}},
'How Do Big Four, Mid-Tier, Specialist and Local Firms Differ?':{dimensions:['Big Four','Mid-tier firm','Specialist firm','Local firm','Engagement fit','Group coordination'],intro:'This chapter compares four common firm types and explains why they are categories of positioning, not a quality ranking.',scope:'Firm types describe how a firm is positioned, not rungs of a quality ladder. The largest global networks, often called the Big Four, can coordinate audits of complex multinational groups. Mid-tier firms sit between the largest networks and local practices and may serve a range of client segments. Specialist firms concentrate on a sector or service and compete on depth and senior attention. Local firms compete on local context and attention. Which type suits an engagement depends on the entity, its complexity and location, and the competence and independence the work requires.',insight:'Choose and compare firms by fit for a defined engagement, meaning authorization, independence, competence and capacity, not by size or brand. Any type can perform a poor audit and any type can perform an excellent one; evidence of quality is what matters.',example:'A multinational group with components in several countries may need a firm able to coordinate group work. A company in a specialized sector may value a specialist’s depth, and a small local company may prefer a local firm’s senior attention and context. For each, the test is the same: is the firm authorized, independent, competent and resourced for this engagement?',vietnam:'Compare firms only within engagements they are authorized, independent, competent and resourced to perform, and check current licensing and quality evidence. Do not rank firms by network brand, historical prestige, headcount or unmatched revenue.',sources:['iaasbHandbook','iaasbQuality','iesba','vnAuditLaw'],definitions:{'Big Four':'A common market label for the largest global audit networks; it describes scale and reach, not a quality ranking.','Mid-tier firm':'A firm or network between the largest global networks and local practices in scale; it may serve many client segments with narrower geographic reach.','Specialist firm':'A firm that concentrates on a sector, service or type of engagement and competes on depth of expertise and senior attention.','Local firm':'A smaller practice serving mainly local clients and competing on local knowledge and attention.','Engagement fit':'Whether a firm is authorized, independent, competent and sufficiently resourced to perform a specific engagement; it is the basis for comparing firms.'}},
"Which Firms and Institutions Shape Vietnam's Audit Market?":{dimensions:['International network','Domestic firm','Smaller practice','Oversight and licensing','Standard adoption','Professional ethics'],intro:'This chapter identifies the kinds of firm and the legal and professional framework that shape who can audit what in Vietnam.',scope:'Vietnam’s audit market is shaped by three kinds of firm and by the framework around them. International networks, domestic firms and smaller practices compete across statutory, foreign-invested, listed, group and local client segments. The Law on Independent Audit (No. 67/2011/QH12) and Circular 214/2012/TT-BTC on Vietnam Auditing Standards set conditions for practising and the standards applied. Professional and international standard setters such as the IAASB and the IESBA influence Vietnam through adoption. Which authority performs each licensing, supervisory or standard-setting role must be verified from current official sources.',insight:'Market position in Vietnam depends on meeting local legal, standards and independence requirements as well as on size or brand. Institutions shape who may audit what and by which standards, and international standards matter only to the extent they are adopted.',example:'A foreign-invested company with an overseas parent can need both a local statutory audit and work for group reporting. A firm that wants the engagement must be authorized locally, apply the standards that govern the local audit and coordinate with the group’s instructions.',vietnam:'Use current official sources, such as the National Legal Database and the Official Gazette, to confirm licensing authorities, oversight arrangements, effective dates and amendments before naming any institution or role. Law 67/2011/QH12 is partially effective, and later amendments to Circular 214/2012/TT-BTC and any added standards must be checked.',sources:['vnAuditLaw','vnStandards','iaasbHandbook','iesba','iaasbQuality'],definitions:{'International network':'A network of firms in several countries to which a Vietnamese firm may belong; it brings reach and common methods but does not replace local licensing and requirements.','Domestic firm':'A firm based in Vietnam that is not a member of an international network; it competes on local knowledge, regulatory readiness and relationships.','Smaller practice':'A small audit practice, often serving local clients or particular segments, with limited capacity for complex or group engagements.','Oversight and licensing':'The legal framework under which audit firms and auditors are authorized and supervised in Vietnam; the Law on Independent Audit (No. 67/2011/QH12) and its implementing rules are the starting point.','Standard adoption':'The step by which Vietnam applies auditing standards, as Vietnam Auditing Standards under Circular 214/2012/TT-BTC, rather than applying international standards directly; status must be checked for each standard.'}},
'Why Do Independence, Expertise and Professional Skepticism Matter?':{dimensions:['Independence','Technical expertise','Professional skepticism','Sector expertise','Management representation'],intro:'This chapter explains why independence, expertise and professional skepticism underpin trust in an audit opinion.',scope:'Three attributes underpin trust in an audit opinion. Independence means the auditor’s judgment is not compromised and is not seen to be compromised, which is why the IESBA Code treats it as a condition of credible assurance. Expertise, both technical and sector, lets the auditor recognize where misstatement could arise and what evidence is appropriate. Professional skepticism is the questioning mind that critically assesses evidence, including contradictory information and management’s explanations, rather than accepting them at face value. If one fails, the others cannot make up for it.',insight:'Independence, expertise and skepticism are success factors because users cannot see the audit work: they trust the conclusion only if the auditor was objective, competent and critical. A failure in any one weakens quality and reputation together.',example:'An auditor with strong technical skill but a close financial relationship with the client may not be seen as independent. An independent but inexperienced team may not recognize an unusual estimate. A competent, independent team that accepts management’s explanation without corroboration has not applied skepticism. Each gap undermines the same conclusion.',vietnam:'Apply the independence and ethics requirements in force in Vietnam and the Vietnam Auditing Standards that govern each engagement. The IESBA Code and ISAs are international references, so their local adoption and any differences must be verified. Staffing should match the competence and sector knowledge the engagement requires.',sources:['iesba','iaasbHandbook','iaasbQuality','vnAuditLaw','vnStandards'],definitions:{'Independence':'Freedom from conditions that compromise objectivity, including independence of mind and independence in appearance, under the applicable requirements.','Technical expertise':'Knowledge of auditing, accounting and reporting requirements needed to identify and evaluate the risk of misstatement.','Professional skepticism':'A questioning mind and critical assessment of audit evidence, including contradictory information and potential bias.','Sector expertise':'Understanding of an industry’s business, risks and typical estimates, which helps the auditor recognize what could be misstated.','Management representation':'A statement by management to the auditor, for example about the completeness of information; it supports but cannot replace other audit evidence.'}},
'How Do Methodology, Evidence and Quality Management Create Trust?':{dimensions:['Risk-based methodology','Sufficient appropriate evidence','Audit documentation','Quality management','Monitoring and remediation','Inspection response'],intro:'This chapter explains how a consistent method, documented evidence and firm-level quality management make audit quality demonstrable.',scope:'Trust in an audit rests on things users and regulators can see are in place. A consistent risk-based methodology, as in ISA 315 (Revised 2019), directs work to where misstatement is most likely. Sufficient appropriate evidence and audit documentation show what supports the conclusion. Firm-level quality management under ISQM 1 sets quality objectives, identifies risks to them, implements responses, monitors results and remediates root causes. Together they make quality demonstrable to clients and regulators rather than merely asserted.',insight:'Reputation is accumulated professional performance and ethics. It is sustained by evidence of quality, meaning a consistent method, documented evidence and effective remediation, and not by policy documents alone.',example:'IAASB quality standards emphasize proactive monitoring, root causes and timely remediation rather than policy documents alone. A firm that finds a recurring documentation weakness, traces its cause, changes its process and checks that the change worked shows quality in a way a policy manual cannot.',vietnam:'Assess a firm on current licensing, quality controls, relevant experience, regulatory or inspection context, delivery capacity and independence, not historical prestige alone. Confirm how ISQM 1 and ISA 315 (Revised 2019) are adopted in Vietnam rather than assuming the international edition applies.',sources:['iaasbQuality','iaasbHandbook','isa315','vnAuditLaw','vnStandards'],definitions:{'Risk-based methodology':'An approach in which the auditor identifies and assesses risks of material misstatement and designs procedures in response, as in ISA 315 (Revised 2019).','Sufficient appropriate evidence':'Evidence with enough quantity and suitable quality, including relevance and reliability, to support conclusions.','Audit documentation':'The record of procedures performed, evidence obtained and conclusions reached, which lets others understand how the conclusion was reached.','Quality management':'Firm and engagement systems for achieving quality objectives, identifying risks, implementing responses, monitoring and remediation.','Monitoring and remediation':'Proactive monitoring of whether quality objectives are met, finding root causes of deficiencies and correcting them in time.'}},
'How Do Talent, Technology and Client Governance Support Sustainable Growth?':{dimensions:['Talent pipeline','Governed technology','Client acceptance and continuance','Client concentration','Growth pace','Fee pressure'],intro:'This chapter explains why talent, technology and client governance must expand together for audit-firm growth to stay sustainable.',scope:'Sustainable growth means adding work only as fast as quality can be maintained. Talent provides the capacity: recruitment, qualification, retention and development decide whether more engagements can be staffed and supervised. Technology adds productivity only when tools are fit for purpose and governed, with outputs critically assessed. Client governance, meaning acceptance, continuance and attention to concentration and fee pressure, decides which work the firm takes and whether commercial pressure can override independence or evidence. The three work as a set; strength in one does not offset a gap in another.',insight:'Growth is sustainable when talent, technology and client governance expand together. Growth that outpaces any of them tends to appear as thinner supervision, reduced evidence or weakened independence before it appears as a commercial problem.',example:'A firm wins several large clients in one year. If hiring, supervision and tool validation do not keep pace, and one client becomes a large share of revenue, review effort rises, deadlines tighten and pressure on judgments grows. Results look strong until quality indicators or an inspection reveal the strain.',vietnam:'Plan staged growth: confirm client eligibility and independence before acceptance, match staffing to peak deadlines, language and sector needs, and test tools for accuracy, access and data protection under Law No. 91/2025/QH15 before scaling. Verify the legal and regulatory requirements that govern capacity and acceptance for each engagement.',sources:['iaasbQuality','technology','iesba','vnAuditLaw','vnData'],definitions:{'Talent pipeline':'The flow of qualified people, from recruitment through development to retention, that gives a firm capacity to take on more work without lowering quality.','Governed technology':'Technology adopted for a defined evidence or workflow problem and used under validation, human review, confidentiality controls and monitoring.','Client acceptance and continuance':'The firm’s decision to take on or keep a client after assessing integrity, independence, competence and capacity.','Client concentration':'Dependence on a few clients for a large share of revenue, which can amplify commercial pressure on independence, staffing and evidence.','Growth pace':'The speed at which a firm adds clients, engagements or services compared with its capacity to staff, supervise and review them.'}},
'How Are Corporate Reporting and Stakeholder Expectations Changing?':{dimensions:['Financial reporting','Sustainability information','Stakeholder expectation','Assurance scope','Suitable criteria','Reporting requirement'],intro:'This chapter explains how widening corporate reporting and stakeholder expectations change what can be assured and what cannot.',scope:'Corporate reporting is widening from financial statements toward other information stakeholders use, including sustainability and other non-financial disclosures. Investors, lenders and regulators can ask what assurance, if any, sits behind that information. ISAE 3000 (Revised) covers assurance other than audits or reviews of historical financial information, and ISSA 5000 is the final international standard for sustainability assurance, effective for periods beginning on or after 15 December 2026 with earlier application permitted. Whether assurance is possible depends on suitable criteria, reliable data and the agreed scope, not on stakeholder interest alone.',insight:'Stakeholder expectations can run ahead of legal requirements. Demand for assurance over wider reporting is real only where requirements, suitable criteria, reliable data and qualified practitioners exist; a change in what is reported changes what can be assured.',example:'An entity starts to publish emissions information and its lenders ask for assurance. Before agreeing, the practitioner needs to know the criteria, how the data is controlled, which period and boundary it covers and what conclusion is possible. Without these, the engagement cannot give the conclusion stakeholders expect.',vietnam:'Verify whether, when and under which framework sustainability reporting or assurance applies to an entity in Vietnam before promising a conclusion, and keep Vietnamese legal requirements separate from international standards that are final but not yet generally effective.',sources:['issa5000','otherEngagements','iaasbHandbook','vnAuditLaw','vnStandards'],definitions:{'Financial reporting':'The preparation of financial statements under an applicable framework; it is the information on which a statutory audit gives its opinion.','Sustainability information':'Information on environmental, social, governance and similar matters, such as emissions, reported by an entity; its data, boundaries and estimates differ from those of financial statements.','Stakeholder expectation':'What investors, lenders, regulators and other users expect of reported information and of the assurance given over it; expectations can run ahead of legal requirements.','Assurance scope':'The subject matter, period and information an assurance engagement covers; it defines what the conclusion applies to and what it does not.','Suitable criteria':'Benchmarks used to measure or evaluate subject matter in an assurance engagement.'}},
'Why Are Audit Quality and Transparency More Important?':{dimensions:['Audit quality','Transparency','User reliance','Quality management','Inspection and remediation','Quality indicator'],intro:'This chapter explains why audit quality and transparency matter more as more decisions depend on audited information.',scope:'Users cannot see audit work; they rely on the report and on evidence about quality. Standards respond with firm-level quality management under ISQM 1, ISQM 2 and ISA 220 (Revised), effective internationally from 15 December 2022: quality objectives, risk identification, responses, monitoring and remediation. Transparency adds to this. Quality indicators and clear explanations of what the audit did and what the report gives assurance on let users, governance bodies and regulators judge quality instead of assuming it. Quality and transparency reinforce each other.',insight:'A firm earns trust by showing evidence of quality and of fixing weaknesses, and transparency is credible only if it reports honestly on both strengths and findings.',example:'A firm’s inspection identifies a recurring weakness in testing estimates. The firm finds the root cause, changes training and review, and later shows that follow-up engagements improved. Sharing that sequence with audit committees tells them more than a statement that quality is a priority.',vietnam:'Assess firms on current licensing, quality controls and inspection or regulatory context. Confirm how the international quality-management standards are adopted in Vietnam; an international effective date does not by itself show local adoption.',sources:['iaasbQuality','iaasbHandbook','iesba','vnAuditLaw','vnStandards'],definitions:{'Audit quality':'The extent to which an audit is performed with enough independence, competence, evidence and review to support a reliable conclusion; it is judged through evidence, not through fees or hours.','Transparency':'Openness about what an audit or a firm did, such as scope, results and quality measures, so users and oversight bodies can judge it; it informs trust and does not replace it.','User reliance':'The confidence users place in audited information when making decisions; it is justified only when the audit was independent and properly performed.','Quality management':'Firm and engagement systems for achieving quality objectives, identifying risks, implementing responses, monitoring and remediation.','Inspection and remediation':'Review of a firm’s quality system and engagements by an oversight body, and the firm’s timely correction of findings and their root causes.'}},
'What Role Can AI Play—and Not Play—in Audit Judgment?':{dimensions:['AI-assisted analysis','Automation bias','Overreliance','Human verification','Professional judgment','Tool governance'],intro:'This chapter explains what AI can support in an audit and what must stay with the engagement team.',scope:'AI can support audit work by helping to analyze populations, detect anomalies, extract and summarize documents and support review, which can improve risk identification and efficiency. It cannot take over audit judgment: evaluating evidence, exercising professional skepticism and taking responsibility for the conclusion remain with the engagement team. IAASB technology material warns about automation bias and overreliance and expects information and outputs to be assessed critically. Using AI therefore needs approved, secure tools, data controls, validation, human verification, documentation and a clear statement of limitations.',insight:'AI changes how evidence is obtained and risks are found, not who is accountable for the conclusion. Its value depends on governance and critical assessment, and an output that has not been verified is not yet a basis for a conclusion.',example:'A tool flags unusual journal entries and summarizes a contract. The team treats the flags as leads to investigate, checks the underlying records and documents what was verified, what the tool could not do and how the conclusion was reached. Accepting the summary, or the absence of flags, as proof would be automation bias.',vietnam:'Use approved, secure tools with data location, access and confidentiality controls, validation, human verification, documentation, limitations and incident response, and confirm duties under the Law on Personal Data Protection (No. 91/2025/QH15) when client data enters a tool.',sources:['technology','iaasbHandbook','iaasbQuality','vnData'],definitions:{'AI-assisted analysis':'Use of artificial-intelligence tools to support audit tasks such as anomaly detection, extraction, summarizing or review support; the output is an input to judgment, not a conclusion.','Automation bias':'The tendency to accept a tool’s output without enough critical assessment because it came from a system.','Overreliance':'Depending on a tool’s output beyond what its reliability and fitness for purpose justify.','Human verification':'Review of a tool’s outputs and the underlying information by a competent person, who decides what they mean and documents the result.','Professional judgment':'The auditor’s application of training, knowledge and experience to decisions about risk, evidence and conclusions; it stays with the auditor and cannot be delegated to a tool.'}},
'How Are Shared Delivery and Specialist Models Developing?':{dimensions:['Shared delivery centre','Specialist','Engagement accountability','Supervision and review','Data protection','Framework alignment'],intro:'This chapter explains how shared delivery centres and specialists can support an audit while accountability stays with the engagement team.',scope:'Audit work can be organized so that some tasks are done by shared delivery centres and some by specialists in areas such as IT, valuation, tax or sustainability, while the engagement team stays responsible for the audit. The model works only if the team directs, supervises and reviews that work, evaluates specialists’ competence and results, keeps independence requirements in view for everyone involved and protects data as it moves. ISA 220 (Revised) keeps the engagement partner responsible for managing and achieving quality, and ISA 600 (Revised) does the same for the group engagement partner when work is spread across components.',insight:'Shared delivery and specialists add capacity and expertise, not accountability. Each added participant widens what must be directed, reviewed and protected, so quality depends on supervision, competence checks, independence and data controls, not on where the work is done.',example:'A team sends routine follow-up tasks to a shared centre and brings in a valuation specialist for a complex estimate. The engagement team defines the tasks, reviews the results, evaluates the specialist’s competence and work, and keeps client data within agreed secure channels. If it cannot do so, it should not rely on the work.',vietnam:'Where client data is shared across locations, define data location, access, confidentiality, secure transfer and retention, and confirm duties under Law No. 91/2025/QH15. Keep local statutory work distinct from group instructions, and confirm that everyone involved meets the independence and competence requirements that apply in Vietnam.',sources:['iaasbQuality','isa600','iesba','technology','vnData'],definitions:{'Shared delivery centre':'A centralized team, which may sit in another location or entity, that performs defined audit tasks for several engagements under the engagement team’s direction.','Specialist':'An individual or firm with expertise in a field other than accounting or auditing, such as IT, valuation, tax or sustainability, whose work the engagement team uses and evaluates.','Engagement accountability':'The engagement partner’s responsibility for the quality of the engagement and its conclusion, which does not transfer when work is performed elsewhere or by specialists.','Supervision and review':'Direction of the people doing the work and review of what they did, which applies equally to shared-centre staff and specialists.','Data protection':'Controls and legal duties for protecting confidential and personal data when it is transferred, stored or processed outside the engagement location.'}},
'How Are Audit Firms Expanding Assurance Capabilities?':{dimensions:['Adjacent assurance service','Subject matter competence','Methodology','Quality management system','Engagement acceptance','Independence check'],intro:'This chapter explains what a firm needs in place, beyond market demand, before it can credibly add a new kind of assurance service.',scope:'Firms expand beyond financial statement audit by adding assurance over other subject matter, such as sustainability information, controls and technology. Each addition needs more than demand: a suitable standard (ISAE 3000 (Revised) for assurance other than audits or reviews of historical financial information, or ISSA 5000 for sustainability assurance), people or specialists with competence in the subject matter, a methodology that applies the standard, extension of the firm’s quality management system to the new service, and acceptance and independence checks for each engagement. Capability built before these are in place risks conclusions the firm cannot support.',insight:'Capability, not demand, is the limit on expanding assurance. A new service is credible only when the standard, competence, methodology, quality system and independence are ready, and a firm should be willing to decline work it cannot support.',example:'A firm wants to offer assurance over a client’s emissions information. It confirms the criteria, hires or engages people who understand the data, adopts a methodology based on the applicable standard, brings the service within its quality monitoring and checks that no other service it provides to the client threatens independence. Only then does it accept the engagement.',vietnam:'Before offering a new assurance service in Vietnam, verify whether the service and its reporting framework exist in Vietnamese law and practice, which standard governs the work and which licensing and independence requirements apply. ISSA 5000 is final but generally effective only for periods beginning on or after 15 December 2026, so do not present it as current Vietnamese practice without verification.',sources:['otherEngagements','issa5000','iaasbQuality','iesba','technology'],definitions:{'Adjacent assurance service':'An assurance engagement beyond the financial statement audit, such as over sustainability information, controls or technology, performed under a standard such as ISAE 3000 (Revised) or ISSA 5000.','Subject matter competence':'The knowledge and experience, in the team or in specialists, needed to evaluate a particular subject matter such as emissions data or IT controls.','Methodology':'The firm’s documented approach for performing a type of engagement consistently and in line with the applicable standard.','Quality management system':'The firm-level system of objectives, risk identification, responses, monitoring and remediation under ISQM 1, which must cover new service lines as well as audit.','Engagement acceptance':'The decision to take on an engagement only after confirming suitable criteria, competence, independence and the conditions the standard requires.'}},
'How Are Cybersecurity, Data and Technology Assurance Evolving?':{dimensions:['IT general control','Application control','Third-party risk','Data integrity','Cyber assurance','Evidence security','Specialist integration'],intro:'This chapter explains how technology risk enters audit and assurance work and why conclusions stay bounded by scope and criteria.',scope:'Technology creates risk in two ways relevant to assurance. In financial reporting, IT general controls, application controls, data integrity and reliance on outside providers affect whether information can be relied on, so they shape risk assessment and evidence. Separately, a practitioner may be engaged to give assurance on controls or other digital subject matter under a standard such as ISAE 3000 (Revised). In either case the conclusion is bounded by the defined scope, suitable criteria, evidence obtained and the practitioner’s competence, often with specialists involved.',insight:'Digital assurance conclusions remain bounded by defined scope, suitable criteria, evidence and practitioner competence. Assurance over cyber controls reports on those controls against criteria; it does not certify that a system is secure.',example:'A controls assurance engagement does not guarantee immunity from every cyber threat or future incident. A conclusion that specified controls operated effectively over a period says nothing about controls outside the scope or about the time after the period.',vietnam:'Define the system, period, control objective, criteria, locations, providers, limitations, specialist role, evidence and data-protection duties, and confirm duties under Law No. 91/2025/QH15. Verify which Vietnamese Standards on Auditing or other requirements apply to the engagement.',sources:['otherEngagements','technology','vnData','vnStandards'],definitions:{'IT general control':'A control over the IT environment, such as access, change management and operations, on which the reliable working of applications and data depends.','Application control':'A control within a specific application that helps ensure transactions are processed completely and accurately.','Third-party risk':'Risk arising from reliance on outside providers, such as hosting or software services, whose controls and data handling the entity or auditor cannot directly manage.','Data integrity':'The completeness, accuracy and consistency of data over its life, which determines whether it can be used as evidence.','Cyber assurance':'An assurance engagement on a defined cybersecurity subject matter, such as a description of controls or specified controls, whose conclusion is limited to the scope and criteria used.'}}}
;

const unique=<T,>(items:T[],key:(item:T)=>string)=>Array.from(new Map(items.map(item=>[key(item),item])).values());
function auditLegacyTargets(module:number,lesson:string,sourceCount:number,targetCount:number){const explicit=AUDIT_LEGACY_TARGETS[`${module}:${lesson}`];if(explicit&&explicit.length===sourceCount)return explicit;return Array.from({length:sourceCount},(_,i)=>Math.round(i*(targetCount-1)/Math.max(1,sourceCount-1)))}
export function standardizeAuditLessons(module:number,lessons:AuditLesson[]):AuditLesson[]{return lessons.map(([lesson,items])=>{const titles=AUDIT_CANONICAL_TITLES[module]?.[lesson]??items.map(item=>item.title);const groups=titles.map(()=>[]as number[]);const targets=auditLegacyTargets(module,lesson,items.length,titles.length);targets.forEach((target,legacyIndex)=>groups[Math.max(0,Math.min(titles.length-1,target))].push(legacyIndex));const sourceForTarget=titles.map((_,targetIndex)=>{let best=0;let distance=Infinity;targets.forEach((target,sourceIndex)=>{const nextDistance=Math.abs(target-targetIndex);if(nextDistance<distance){distance=nextDistance;best=sourceIndex}});return best});const next=titles.map((title,index)=>{const legacyIndexes=groups[index];const sourceIndex=sourceForTarget[index];const base=items[sourceIndex];const siblings=sourceForTarget.map((value,targetIndex)=>({value,targetIndex})).filter(row=>row.value===sourceIndex);const rank=Math.max(0,siblings.findIndex(row=>row.targetIndex===index));const sourceItems=legacyIndexes.length?legacyIndexes.map(i=>items[i]):[base];const dimensions=legacyIndexes.length>1?Array.from(new Set(sourceItems.flatMap(item=>item.dimensions))):base.dimensions.filter((_,i)=>i%siblings.length===rank);const focusedDimensions=dimensions.length?dimensions:[base.dimensions[rank%base.dimensions.length]];const detail=AUDIT_DETAILS[title];return{title,dimensions:detail?.dimensions??focusedDimensions,insight:detail?.insight??`${base.insight} This chapter focuses specifically on ${focusedDimensions.join(', ')}.`,scope:detail?.scope??`${title} examines ${focusedDimensions.join(', ')}. ${base.scope}`,example:detail?.example??sourceItems.map(item=>item.example).join(' '),vietnam:detail?.vietnam??sourceItems.map(item=>item.vietnam).join(' '),sources:detail?.sources??unique(sourceItems.flatMap(item=>item.sources),id=>id),intro:detail?.intro,definitions:detail?.definitions,stats:sourceItems.flatMap(item=>item.stats??[]),legacyIndex:legacyIndexes[0],legacyIndexes,legacyCompletionIndex:legacyIndexes[0]}});return[lesson,next]})}
export function buildAuditLegacyManifest(module:number,lessons:AuditLesson[]){const standardized=standardizeAuditLessons(module,lessons);return standardized.flatMap(([lesson,items],lessonIndex)=>items.flatMap((item,successorIndex)=>(item.legacyIndexes??[]).map(legacyIndex=>({module,lesson,lessonIndex,legacyIndex,legacyTitle:lessons[lessonIndex][1][legacyIndex]?.title??'',legacyObjective:`Explain ${lessons[lessonIndex][1][legacyIndex]?.title.toLowerCase()??'the original chapter'}.`,successorIndex,successorTitle:item.title,sources:lessons[lessonIndex][1][legacyIndex]?.sources??[],migrationVersion:'professional-audit-full-v1'}))))}

const definitions:Record<string,string>={'Reasonable assurance':'A high but not absolute level of assurance supported by sufficient appropriate evidence and reduced audit risk.','Limited assurance':'A lower level of assurance than reasonable assurance, expressed in the form required by the applicable standard.','Material misstatement':'A misstatement that could reasonably influence intended users under the applicable materiality context.','Professional skepticism':'A questioning mind and critical assessment of evidence, including contradictory information and potential bias.','Sufficient appropriate evidence':'Evidence with enough quantity and suitable quality, including relevance and reliability, to support conclusions.','Independence':'Freedom from conditions compromising objectivity, including independence of mind and appearance under applicable requirements.','Engagement quality review':'An objective evaluation of significant judgments and conclusions by an eligible reviewer where required.','Component auditor':'An auditor who performs work related to a component for purposes of a group audit.','Agreed-upon procedures':'Specified procedures with factual findings; intended users draw their own conclusions and no assurance conclusion is expressed.','Materiality':'The magnitude or nature of a matter that could influence intended users in context.','Audit risk':'Risk of expressing an inappropriate audit opinion when the financial statements are materially misstated.','Quality management':'Firm and engagement systems for achieving quality objectives, identifying risks, implementing responses, monitoring and remediation.','Realization':'Fees earned relative to recorded or standard billable effort under a defined basis.','Utilization':'Chargeable or productive time relative to available professional capacity under a stated definition.','Contradictory evidence':'Information inconsistent with other evidence or the expected conclusion and requiring evaluation.','Suitable criteria':'Benchmarks used to measure or evaluate subject matter in an assurance engagement.','Inherent risk':'Susceptibility of an assertion to material misstatement before considering related controls.','Control risk':'Risk that a material misstatement will not be prevented, or detected and corrected, by relevant controls.','Detection risk':'Risk that audit procedures will not detect an existing material misstatement.','Performance materiality':'Amount set below overall materiality to reduce aggregation risk to an appropriately low level under the applicable standard.','Unmodified opinion':'Opinion that the financial statements are presented, in all material respects, in accordance with the applicable framework.','Qualified opinion':'Modified opinion used for a material but not pervasive misstatement or evidence limitation under applicable reporting requirements.','Adverse opinion':'Modified opinion for material and pervasive misstatement under applicable reporting requirements.','Disclaimer of opinion':'Outcome when sufficient appropriate evidence cannot be obtained and possible effects could be material and pervasive, subject to the applicable standard.'};const terms=(a:string[],own?:Record<string,string>)=>a.slice(0,5).map(term=>({term,definition:own?.[term]??definitions[term]??`A core Audit and Assurance concept related to ${term.toLowerCase()}.`}));function chapter(module:number,lesson:string,item:AuditItem,index:number):AuditCardData{const visual=AUDIT_ASSURANCE_CHAPTER_VISUALS[`professional-audit-m${module}-${index}`];const impact=`For practitioners and firms, ${item.insight.toLowerCase()} Define engagement type, intended user, criteria, standard, evidence, independence, responsibility, reporting output and risk before acting.`;const recap=[item.insight,impact,`Key dimensions include ${item.dimensions.join(', ')}.`];return{title:`${String(index).padStart(2,'0')} ${item.title}`,chapterTitle:lesson,readingTime:'8',legacyIndex:item.legacyIndex,legacyIndexes:item.legacyIndexes,legacyCompletionIndex:item.legacyCompletionIndex,migrationVersion:'professional-audit-full-v1',objective:`Explain ${item.title.toLowerCase()} and apply it to an evidence-based assurance decision.`,mateIntro:item.intro??`This chapter examines ${item.scope}`,keyInsight:item.insight,concepts:[],narrative:[{label:'What it is',text:item.scope},{label:'Why it is happening',text:`Reporting complexity, regulation, technology, stakeholder expectations and expanding information needs make this topic strategically important. ${item.insight}`},{label:'Real-world example',text:item.example},{label:'Vietnam example',text:item.vietnam},{label:'Business impact',text:impact}],visualKind:`professional-audit-m${module}-${index}`as AuditVisualKind,visualHeading:visual?.heading??item.title,visualIntro:visual?.intro??'Use the visual to connect engagement purpose, criteria, risk, evidence, judgment, review, reporting, quality and public trust.',imageAlt:`Casemate Audit and Assurance visual for ${item.title}`,statTiles:item.stats??[{value:String(item.dimensions.length),label:'Engagement dimensions',description:item.dimensions.join(' · ')},{value:String(item.sources.length),label:'Standards sources',description:'Official standard-setter or legal sources with scope and effective-date notes.'},{value:'1',label:'Conclusion test',description:'Define criteria, sufficient appropriate evidence, reviewer challenge and reporting responsibility.'}],statsNote:item.stats?'Figures retain standard, jurisdiction, entity, engagement, period, denominator and effective, proposed or not-yet-effective status.':'Tiles summarize the framework; contract value, hours, evidence volume, audit conclusion, billed revenue, cash and profit are not interchangeable.',keyTerms:terms(item.dimensions,item.definitions),recap,chapterRecap:recap.join(' '),deepDiveTitle:'How independence, evidence and judgment create credible assurance—and where weak scope, review or incentives can fail',body:<F2DeepDive paragraphs={[item.scope,item.insight,item.example,item.vietnam,impact]} evidence="Separate engagement type, criteria, risk, materiality, procedure, evidence relevance and reliability, judgment, review, conclusion, report, client action and economics."/>,sources:item.sources.map(id=>AUDIT_SOURCES[id])}}function seed(chapter:string,q:string,a:string,c:string){return{chapter,objective:q,question:q,application:a,correct:c,wrong:['Treat every professional-service report as the same level and form of assurance','Use a large data volume or automated output without evaluating relevance, reliability and contradictory evidence','Let fee, deadline or client satisfaction override independence, scope, evidence, review or applicable standards']as[string,string,string],explanation:'Audit and assurance decisions require a defined engagement, intended user, suitable criteria, risk, sufficient appropriate evidence, independence, quality review and reporting responsibility.'}}function calculationSeed(chapter:string,question:string,application:string,correct:string,wrong:[string,string,string]){return{chapter,objective:question,question,application,correct,wrong,explanation:'Apply the stated hypothetical assumptions only. Audit judgments, percentages, procedures and sample sizes are not universal prescriptions.'}}
function quiz(prefix:string,topics:string[],chapterCount:number){if(prefix==='professional-audit-m3-l4')return f2Quiz(prefix,[calculationSeed('1','A HYPOTHETICAL audit has a VND1,200m fee and VND1,000m defined delivery cost. What are contribution and margin?','Calculate fee less delivery cost and divide by the fee.','VND200m and 16.7%',['VND1,000m and 83.3%','VND200m and 20%','VND1,200m and 100%']),seed('1','Why must contract value, billing, recognized revenue and cash remain distinct?','An audit reaches a billing milestone before collection. What should be reported?','Each measure separately under its contract and accounting basis'),seed('2','Why can a high-margin audit still have weak quality?','A team proposes reducing required procedures to protect margin. What is the correct response?','Perform and review work required by risk, evidence, independence and applicable standards'),seed('3','How should utilization and realization be interpreted?','A firm compares service lines. What is required?','Defined available hours, chargeable hours, standard value, earned revenue, period and service scope'),seed('3','Why must audit quality indicators remain separate from financial KPIs?','A firm has strong revenue per professional. What does that prove?','It proves an economic result, not sufficient evidence, skepticism, review or audit quality')]);if(prefix==='professional-audit-m2-l3')return f2Quiz(prefix,[seed('1','How does the simplified audit risk model guide planning?','Inherent and control risk are assessed higher. What generally follows?','Lower acceptable detection risk through changed nature, timing or extent of procedures'),seed('1','How does audit risk differ from business risk?','A company faces declining demand. What must the auditor distinguish?','Entity business risk from risk of material misstatement and risk of an inappropriate opinion'),seed('2','How do assertions and controls shape procedures?','Revenue occurrence and cutoff are risks. What should guide testing?','Relevant assertions, control design and implementation, assessed risk and evidence needs'),seed('3','Why does evidence quality matter as well as quantity?','A large dataset comes from an unreliable source. What is required?','Evaluate relevance, reliability, completeness and contradictory evidence'),seed('3','How should sampling respond to assessed risk?','Risk rises for unusual revenue transactions. What is appropriate?','Design or retarget procedures using the population and professional judgment, not a universal sample size')]);return f2Quiz(prefix,topics.slice(0,5).map((topic,i)=>seed(String(i%chapterCount+1),`What is central to ${topic}?`,`An engagement team evaluates ${topic}. What should guide it?`,'Defined engagement, criteria, risk, evidence, judgment, independence, review and reporting')))}export function buildAuditModule(module:number,lessons:AuditLesson[],topics:string[][],next:string[],theme:string){const standardized=standardizeAuditLessons(module,lessons);let visualIndex=0;const decks:Record<string,AuditCardData[]>={};const quizzes:Record<string,FashionM2Question[]>={};const takeaways:Record<string,FashionM2Takeaways>={};standardized.forEach(([lesson,items],i)=>{decks[lesson]=items.map(item=>chapter(module,lesson,item,++visualIndex));quizzes[lesson]=quiz(`professional-audit-m${module}-l${i+1}`,topics[i],items.length);takeaways[lesson]={learned:`You can explain ${lesson.toLowerCase()} across Audit and Assurance.`,keyTakeaways:[`Apply ${theme} to a defined engagement, entity, intended user, criteria, jurisdiction and reporting period.`,`Separate audit, review, other assurance, agreed-upon procedures, advisory, evidence volume, conclusion, fees, cash and profit.`,`Independence, skepticism, competence, evidence, review, documentation and quality management jointly support credibility.`,`Vietnam engagements require current legal, licensing, standards, independence and entity-specific verification.`,`Use sources with explicit standard, engagement scope, jurisdiction, effective date and authoritative status.`],businessImplications:'Accept and scope engagements carefully, protect independence, staff for risk and complexity, obtain and challenge sufficient appropriate evidence, review significant judgments, report clearly, and invest in quality systems and talent.',remember:'An audit provides reasonable—not absolute—assurance; credibility comes from independent, standards-based work supported by evidence and professional judgment.',nextLesson:next[i]??''}});return{decks,quizzes,takeaways}}export function buildAuditVisuals(module:number,lessons:AuditLesson[]){const standardized=standardizeAuditLessons(module,lessons);const specs:Record<string,VisualSpec>={};let index=0;standardized.forEach(([,items])=>items.forEach(item=>{const key=`professional-audit-m${module}-${++index}`;specs[key]=AUDIT_ASSURANCE_CHAPTER_VISUALS[key]?.spec??{layout:'taxonomy',title:item.title,kicker:'',root:item.title,rootDetail:'Factors considered together, not in sequence',groups:Array.from(new Set(item.dimensions)).map(label=>({label})),takeaway:item.insight}}));return specs}export function renderAuditVisual(specs:Record<string,VisualSpec>,kind:AuditVisualKind){const spec=specs[kind];return spec?<VisualView spec={spec}/>:null}
